    }
    const shackle = tor(.06, .012, m, .1, .2, .14); g.add(shackle);
    return row([g], 'torso');
  };

  B.skullPauldrons = chr => {
    const out = [['torso', null]];
    [-1, 1].forEach(sd => {
      const side = sd < 0 ? 'L' : 'R';
      const g = new THREE.Group();
