      plate.position.set(0, .04, 0); g.add(plate);
      for (let i = 0; i < 3; i++) {
        const sk = sph(.045, M.bone(), -.05 + i * .05, .055, RC.rand(-.02, .02));
        sk.scale.y = .8; g.add(sk);
        [-1, 1].forEach(zz => {
