let line = 1;
let state = 'code'; // code | line | block | s | d | t | re skip template
let prev = '';
for (let i = 0; i < t.length; i++) {
  const c = t[i];
  const n = t[i + 1];
  if (c === '\n') line++;
  if (state === 'block') { if (c === '*' && n === '/') { state = 'code'; i++; } continue; }
  if (state === 'line') { if (c === '\n') state = 'code'; continue; }
  if (state === 's') { if (c === '\\') { i++; continue; } if (c === "'") state = 'code'; continue; }
  if (state === 'd') { if (c === '\\') { i++; continue; } if (c === '"') state = 'code'; continue; }
  if (state === 't') { if (c === '\\') { i++; continue; } if (c === '`') state = 'code'; continue; }
  if (c === '/' && n === '/') { state = 'line'; i++; continue; }
  if (c === '/' && n === '*') { state = 'block'; i++; continue; }
  if (c === "'") { state = 's'; continue; }
  if (c === '"') { state = 'd'; continue; }
  if (c === '`') { state = 't'; continue; }
  if (c === '{') depth++;
  if (c === '}') depth--;
}
